import json, subprocess, time, sys
latest_id = None
for i in range(6):
    p = subprocess.run(['archon','workflow','runs','--limit','10','--json'], capture_output=True, text=True)
    if p.returncode != 0:
        print(f'poll {i+1}: archon workflow runs failed')
        print(p.stderr.strip())
        time.sleep(3)
        continue
    data = json.loads(p.stdout)
    runs = data.get('runs', [])
    target = None
    for r in runs:
        if r.get('workflow_name') == 'plan-feature' and 'Plan the next phase of Project Koios for multi-repo execution readiness' in r.get('user_message',''):
            target = r
            latest_id = r['id']
            break
    if target:
        print(f"poll {i+1}: id={target['id']} status={target['status']} started_at={target.get('started_at')} completed_at={target.get('completed_at')}")
        meta = target.get('metadata') or {}
        if 'node_counts' in meta:
            print('  node_counts=', meta['node_counts'])
        if target['status'] in ('completed','failed','cancelled'):
            break
    else:
        print(f'poll {i+1}: target run not visible yet')
    time.sleep(3)

if latest_id:
    p = subprocess.run(['archon','workflow','get',latest_id,'--verbose','--json'], capture_output=True, text=True)
    print('\nDETAIL:')
    if p.returncode == 0:
        print(p.stdout)
    else:
        print(p.stderr.strip())
